const input = $input.first().json || {};
const secret = String(input.headers?.['x-ai-job-automation-webhook-secret'] || '');
if (!String($env.N8N_WEBHOOK_SECRET || '') || secret !== String($env.N8N_WEBHOOK_SECRET)) throw new Error('Webhook authentication failed');
const request = input.body || input;
if (!request.presentation_key || !Array.isArray(request.canonical_member_keys) || !request.source || !request.external_id || !request.sheet_name || !request.columns) throw new Error('Invalid application CRM sync request');
return [{ json: request }];

const request = $('Validate and Normalize Application CRM Sync').first().json;
const rows = $input.all().map(item => item.json || {});
const byKey = new Map(rows.map(row => [String(row['CRM Key'] || '').trim(), row]).filter(([key]) => key));

function normalizeUrl(value) {
  const trimmed = String(value || '').trim();
  const markdownLink = /^\[[^\]]*\]\((https?:\/\/[^()\s]+)\)$/i.exec(trimmed);
  return markdownLink ? markdownLink[1] : trimmed;
}

function extractHhExternalId(value) {
  let decoded = normalizeUrl(value);
  for (let attempt = 0; attempt < 3 && decoded; attempt += 1) {
    try {
      const parsed = new URL(decoded);
      if (/(^|\.)hh\.ru$/i.test(parsed.hostname)) {
        const vacancyMatch = /^\/vacancy\/(\d+)(?:\/|$)/i.exec(parsed.pathname);
        if (vacancyMatch) return vacancyMatch[1];
        const backUrlMatch = /(?:[?&]backUrl=)\/vacancy\/(\d+)(?:[\/?#&]|$)/i.exec(decoded);
        if (backUrlMatch) return backUrlMatch[1];
      }
    } catch (_) {
      // The next decode pass may turn an encoded URL into a parseable URL.
    }
    try {
      const next = decodeURIComponent(decoded);
      if (next === decoded) break;
      decoded = next;
    } catch (_) {
      break;
    }
  }
  return null;
}

let row = byKey.get(String(request.presentation_key));
let matchStrategy = 'business_key';
if (!row) {
  for (const key of request.canonical_member_keys) {
    if (byKey.has(String(key))) {
      row = byKey.get(String(key));
      matchStrategy = 'legacy_crm_key_fallback';
      break;
    }
  }
}
if (!row && request.source === 'hh' && request.external_id) {
  const targetExternalId = String(request.external_id);
  const exactMatches = rows.filter(candidate => extractHhExternalId(candidate['Ссылка']) === targetExternalId);
  if (exactMatches.length > 1) return [{ json: { found: false, error_code: 'crm_row_ambiguous' } }];
  if (exactMatches.length === 1) {
    row = exactMatches[0];
    matchStrategy = 'exact_hh_url_fallback';
  }
}
if (!row) return [{ json: { found: false, error_code: 'crm_row_not_found' } }];
const columns = request.columns || {};
return [{ json: { found: true, match_strategy: matchStrategy, '№': row['№'] || row['No'], 'CRM Key': request.presentation_key, 'Отклик': columns['Отклик'] || '', 'Ответ': columns['Ответ'] || '', 'Интервью': columns['Интервью'] || '', 'Итог': columns['Итог'] || row['Итог'] || '', 'Дата отклика': columns['Дата отклика'] || '', 'Текст отклика': columns['Текст отклика'] || '', 'Ответ работодателя': columns['Ответ работодателя'] || '', 'Дата ответа': columns['Дата ответа'] || '', 'Дата интервью': columns['Дата интервью'] || '', 'Комментарий / заметки': columns['Комментарий / заметки'] || '' } }];
